'use strict';
const assert=require('node:assert/strict'),path=require('node:path');
const {ROOT,CANARY,record,session}=require('./r0009-calendar-harness.cjs');
const sourcePath=process.argv[2]||path.join(ROOT,'index.html'), results=[];
const test=(name,body)=>{try{const detail=body();results.push({name,status:'PASS',detail});}catch(error){results.push({name,status:'FAIL',error:error.message});}};
function sameProjection(o){
  assert.ok(o.dateTruth,'Actual last-painted date decision is exposed');
  const d=o.dateTruth;
  assert.equal(o.title,d.explanation,'Actual footer title describes the painted decision');
  assert.equal(o.dialog.reason,d.explanation,'Actual full-value reason describes the painted decision');
  assert.equal(o.dialog.gregorian,d.gregorianText||'Gregorian date unavailable');
  assert.equal(o.dialog.hijri,d.hijriText||'Hijri date unavailable');
  assert.equal(o.dialog.preview,d.previewText);
  assert.equal(o.ahButtonLabel,`Show complete Hijri date: ${d.hijriText||'Hijri date unavailable'}. ${d.explanation}`);
  assert.equal(o.ceButtonLabel,`Show complete Gregorian date: ${d.gregorianText||'Gregorian date unavailable'}`);
  return d;
}
test('before Maghrib real render positive',()=>{const s=session({sourcePath});const o=s.render();assert.match(o.ah,/1448-02-19/);assert.match(o.ahHtml,/mph pre/);assert.match(o.ah,/20$/);return {ce:o.ce,ah:o.ah,current:o.current};});
test('at Maghrib selected tomorrow positive',()=>{const s=session({sourcePath,at:'2026-09-07T18:00:00Z'});const o=s.render();assert.match(o.ah,/1448-02-20/);assert.doesNotMatch(o.ahHtml,/mph pre/);return {ce:o.ce,ah:o.ah};});
test('missing tomorrow is visibly disclosed independently of prayer stale',()=>{const s=session({sourcePath,at:'2026-09-07T18:01:00Z'});s.state(record(),null);const o=s.render();assert.match(o.ah,/1448-02-19/);assert.equal(o.prayerStale,false);assert.match(o.ah,/Sunset date update unavailable/,'Actual retained AH footer must disclose unavailable sunset update');const d=sameProjection(o);assert.equal(d.maghribRollAvailable,false);assert.equal(d.maghribRollApplied,false);assert.equal(d.unavailableReason,'Sunset date update unavailable');assert.equal(d.selectedSource,'today');assert.equal(d.staleDateState,'calendar-unavailable');assert.match(o.title,/could not advance/);assert.doesNotMatch(o.title,/already advanced|Advanced at Maghrib/);return {ah:o.ah,title:o.title,prayerStale:o.prayerStale,dateTruth:d};});
test('wrong-day tomorrow cannot advance actual footer',()=>{const s=session({sourcePath,at:'2026-09-07T18:01:00Z'});s.state(record(),record('09','21'));const o=s.render();assert.match(o.ah,/1448-02-19/,'Wrong Gregorian day must not supply displayed tomorrow AH');assert.match(o.ah,/Sunset date update unavailable/);});
test('wrong-zone tomorrow cannot preview',()=>{const s=session({sourcePath});const next=record('08','20');next.meta.timezone='Asia/Riyadh';s.state(record(),next);const o=s.render();assert.doesNotMatch(o.ahHtml,/mph pre/,'Context-mismatched tomorrow must not preview');});
test('absent both AH values is explicitly unavailable',()=>{const s=session({sourcePath,at:'2026-09-07T18:01:00Z'});const t=record(),n=record('08','20');t.date.hijri=null;n.date.hijri=null;s.state(t,n);const o=s.render();assert.match(o.ah,/Hijri date unavailable/);});
test('late tomorrow arrival clears only calendar reason and is idempotent',()=>{const s=session({sourcePath,at:'2026-09-07T18:01:00Z'});s.state(record(),null);const missing=s.render();assert.match(missing.ah,/Sunset date update unavailable/);s.state(record(),record('08','20'));const a=s.render(),b=s.render();assert.equal(a.ah,b.ah);assert.equal(a.title,b.title);assert.match(a.ah,/1448-02-20/);assert.doesNotMatch(a.ah,/update unavailable/);assert.equal(a.prayerStale,false);const d=sameProjection(a);assert.equal(d.unavailableReason,null);assert.equal(d.maghribRollApplied,true);assert.equal(d.selectedGregorianDay,'08-09-2026');assert.equal(d.selectedSource,'tomorrow');});
test('same-day backwards provider correction remains provider-derived positive',()=>{const s=session({sourcePath});s.state(record('07','10'),record('08','11'));s.render();s.state(record('07','09'),record('08','10'));assert.match(s.render().ah,/1448-02-09/);});
test('midnight accepted-day promotion adds no synthetic Hijri increment positive',()=>{const s=session({sourcePath});s.state(record(),record('08','20'));s.setClock('2026-09-08T00:00:00Z');s.state(record('08','20'),record('09','21'));const o=s.render();assert.match(o.ce,/2026-09-08/);assert.match(o.ah,/1448-02-20/);});
test('selected tomorrow convention is disclosed rather than today convention',()=>{const s=session({sourcePath,at:'2026-09-07T18:01:00Z'});s.state(record(),record('08','20','UAQ'));const o=s.render();assert.match(o.ah,/1448-02-20/);const d=sameProjection(o);assert.match(o.title,/Aladhan; UAQ/);assert.doesNotMatch(o.title,/HJCoSA/);assert.equal(d.hijriMethod,'UAQ');assert.equal(s.evaluate('CONFIG.method'),'4');});
test('missing selected method explicitly reports unavailable convention',()=>{const s=session({sourcePath,at:'2026-09-07T18:01:00Z'});s.state(record(),record('08','20',null));const o=s.render();assert.match(o.ah,/1448-02-20/);sameProjection(o);assert.match(o.title,/calendar convention unavailable/);assert.doesNotMatch(o.title,/HJCoSA|UAQ/);assert.equal(o.dateTruth.hijriMethod,null);});
test('actual dateTruth snapshot agrees with painted boundary and advance',()=>{const s=session({sourcePath,at:'2026-09-07T18:01:00Z'});const o=s.render();assert.match(o.ah,/1448-02-20/);const d=sameProjection(o);assert.equal(d.beforeOrAfterMaghrib,'after');assert.equal(d.maghribRollApplied,true);assert.equal(d.requestedGregorianDay,'07-09-2026');assert.equal(d.loadedGregorianDay,'07-09-2026');assert.equal(d.timezone,'UTC');});
test('reverse boundary correction does not hold tomorrow value positive',()=>{const s=session({sourcePath,at:'2026-09-07T18:01:00Z'});assert.match(s.render().ah,/1448-02-20/);s.setClock('2026-09-07T17:59:59Z');const o=s.render();assert.match(o.ah,/1448-02-19/);assert.match(o.ahHtml,/mph pre/);});
test('accepted duplicate and skipped days have no automatic correction positive',()=>{const s=session({sourcePath});for(const day of ['08','10','10']){s.state(record('07',day),record('08','11'));const o=s.render();assert.match(o.ah,new RegExp('1448-02-'+day));assert.equal(sameProjection(o).hijriAnomaly,null);}});
test('valid month and year transitions retain provider values positive',()=>{const s=session({sourcePath,at:'2026-09-07T18:00:00Z'});const today=record(),next=record('08','01');today.date.hijri={year:'1447',month:{number:11,en:'Dhu al-Qadah'},day:'29'};next.date.hijri={year:'1447',month:{number:12,en:'Dhu al-Hijjah'},day:'01'};s.state(today,next);assert.match(s.render().ah,/1447-12-01/);today.date.hijri={year:'1447',month:{number:12,en:'Dhu al-Hijjah'},day:'30'};next.date.hijri={year:'1448',month:{number:1,en:'Muharram'},day:'01'};s.state(today,next);assert.match(s.render().ah,/1448-01-01/);});
test('model instant and calendar context remain one snapshot across midnight',()=>{const s=session({sourcePath,at:'2026-09-07T23:59:59Z'});s.context.__moveClock=()=>s.setClock('2026-09-08T00:00:00Z');s.evaluate('const originalCalendarModel=model;model=()=>{const m=originalCalendarModel();window.__moveClock();return m;};');const o=s.render();const d=sameProjection(o);assert.equal(d.requestedGregorianDay,'07-09-2026','The date decision consumes the same instant as its prayer boundary');assert.equal(d.beforeOrAfterMaghrib,'after');assert.equal(d.selectedGregorianDay,'08-09-2026');assert.match(o.ah,/1448-02-20/);});
test('wrong current context withholds the model and never relabels old AH as current',()=>{const s=session({sourcePath,at:'2026-09-08T10:00:00Z'});const o=s.render();const d=sameProjection(o);assert.equal(d.requestedGregorianDay,null,'No admitted prayer model is supplied to the calendar');assert.equal(d.selectedSource,null);assert.equal(o.current,'—');assert.match(o.ah,/Hijri date unavailable/);assert.equal(o.prayerStale,false);});
test('invalid optional AH cannot advance or preview',()=>{for(const at of ['2026-09-07T17:59:59Z','2026-09-07T18:01:00Z']){const s=session({sourcePath,at});const next=record('08','31');s.state(record(),next);const o=s.render();assert.match(o.ah,/1448-02-19/);assert.doesNotMatch(o.ahHtml,/mph pre/);assert.equal(sameProjection(o).maghribRollApplied,false);}});
test('missing name is usable numerically and explicitly unavailable for named formats',()=>{for(const format of ['YYYY-MM-DD','DD MMMM YYYY']){const s=session({sourcePath,format});const current=record();delete current.date.hijri.month.en;s.state(current,null);const o=s.render();sameProjection(o);assert.match(o.ah,format==='YYYY-MM-DD'?/1448-02-19/:/Hijri date unavailable/);}});
test('untrusted selected method reaches only literal explanation owners',()=>{const s=session({sourcePath,at:'2026-09-07T18:01:00Z'});s.state(record(),record('08','20',CANARY+' & "التاريخ"'));const o=s.render();const d=sameProjection(o);assert.equal(d.hijriMethod,CANARY+' & "التاريخ"');assert.ok(o.title.includes(CANARY));assert.equal(s.nodes.get('#dateReason').innerHTML.includes('<svg'),false);assert.equal(s.context.__sw_sec_probe,undefined);});
test('last-painted diagnostics do not recompute from unpainted state',()=>{const s=session({sourcePath});const first=s.render();const original=JSON.stringify(first.dateTruth);s.setClock('2026-09-07T18:01:00Z');s.state(record(),record('08','23','UAQ'));assert.equal(JSON.stringify(s.snapshot().dateTruth),original);const painted=s.render();assert.match(painted.ah,/1448-02-23/);assert.equal(sameProjection(painted).hijriMethod,'UAQ');});
test('long sleep followed by accepted current record remains provider-derived',()=>{const s=session({sourcePath});s.render();s.setClock('2026-09-27T10:00:00Z');s.state(record('27','08'),record('28','09'));const o=s.render();assert.match(o.ce,/2026-09-27/);assert.match(o.ah,/1448-02-08/);assert.equal(sameProjection(o).hijriAnomaly,null);});
const identity=session({sourcePath});
console.log(JSON.stringify({sourceSha256:identity.sourceSha256,configSha256:identity.configSha256,environment:'Complete actual inline runtime/config/model; fixed preparse Date; recording DOM; admitted records; async boot/art suspended; no clock/loader/browser qualification',results},null,2));
process.exitCode=results.some(x=>x.status==='FAIL')?1:0;
